CREATE TYPE "OperationalDecision" AS ENUM ('ALLOWED','REVIEW_REQUIRED','DEFERRED'); CREATE TABLE "SafetyChecklist" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tripId" UUID NOT NULL REFERENCES "Trip"("id") ON DELETE RESTRICT,"decision" "OperationalDecision" NOT NULL DEFAULT 'REVIEW_REQUIRED',"items" JSONB NOT NULL,"notes" TEXT,"decidedAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX "SafetyChecklist_tripId_decision_idx" ON "SafetyChecklist" ("tripId","decision");